// 入力: { to: string|string[], subject, body, level?: 'info'|'warn'|'escalation' }
// 出力: { ok, to, level }
//
// チャネル(メール / Slack など)に触れるのはこのワークフローだけ。
// 呼び出し側はこの入出力インターフェースにだけ依存する。
// チャネルを変えるときは後続ノードを差し替え、ここは変えない。
// 設計: docs/design/04-notification-abstraction.md

const inp = $input.first()?.json ?? {};

const to = Array.isArray(inp.to) ? inp.to : (inp.to ? [inp.to] : []);
const valid = to.filter((a) => typeof a === 'string' && /^[^@\s]+@[^@\s]+$/.test(a));
if (valid.length === 0) {
  throw new Error(`notify: 有効な宛先がありません: ${JSON.stringify(inp.to)}`);
}
if (!inp.subject) throw new Error('notify: subject は必須です');

const level = ['info', 'warn', 'escalation'].includes(inp.level) ? inp.level : 'info';
const PREFIX = { info: '', warn: '【注意】', escalation: '【エスカレーション】' };

return [{ json: {
  from: $env.NOTIFY_FROM || 'itops-bot@example.com',
  to: valid.join(','),
  recipients: valid,
  level,
  subject: `${PREFIX[level]}${inp.subject}`,
  body: String(inp.body ?? ''),
}}];

// チャネル固有の応答は呼び出し側に見せない(差し替え可能に保つため)。
const ctx = $('宛先と本文を整える').first().json;
return [{ json: { ok: true, to: ctx.recipients, level: ctx.level } }];
